-- Grouped state/status summaries; execute individually. READ-ONLY only.
-- reconstruction_batches
SELECT state,COUNT(*) batches,SUM(candidate_count) candidate_count,MIN(created_at) first_created,MAX(created_at) last_created,MIN(cancelled_at) first_cancelled,MAX(cancelled_at) last_cancelled FROM loucka_reconstruction.reconstruction_batches GROUP BY state ORDER BY state;
-- reconstruction_candidates_by_variable
SELECT variable,source_database,COUNT(*) candidates,SUM(source_value IS NULL) source_null,SUM(proposed_value IS NULL) proposed_null,MIN(target_time) min_target,MAX(target_time) max_target FROM loucka_reconstruction.reconstruction_candidates GROUP BY variable,source_database ORDER BY variable,source_database;
-- reconstruction_changes_by_state
SELECT state,COUNT(*) events,COUNT(DISTINCT CONCAT(target_time,':',variable)) target_variable_pairs,SUM(old_value IS NULL) old_null,SUM(new_value IS NULL) new_null,SUM(source_value IS NULL) source_null,MIN(created_at) first_created,MAX(created_at) last_created,MAX(applied_at) last_applied FROM loucka_reconstruction.reconstruction_changes GROUP BY state ORDER BY state;
-- humidity_by_decision
SELECT decision,COUNT(*) rows_n,SUM(original_humidity_pct IS NULL) original_null,SUM(proposed_humidity_pct IS NULL) proposed_null,SUM(local_temperature_c IS NULL) local_temp_null,SUM(luhamet_humidity_pct IS NULL) luhamet_rh_null,MIN(target_time) min_target,MAX(target_time) max_target FROM loucka_reconstruction.reconstruction_humidity_202204 GROUP BY decision ORDER BY decision;
-- rain_audit_by_class
SELECT class_code,evidence_level,COUNT(*) rows_n,SUM(proposed_replacement_mm IS NULL) proposal_null,MIN(target_time) min_target,MAX(target_time) max_target FROM loucka_reconstruction.rain_audit_202107 GROUP BY class_code,evidence_level ORDER BY class_code,evidence_level;
-- rain_qc_by_status
SELECT qc_status,confidence_level,source_record_status,COUNT(*) rows_n,SUM(validated_rain_mm IS NULL) validated_null,MIN(target_time) min_target,MAX(target_time) max_target FROM loucka_reconstruction.rain_qc_202107 GROUP BY qc_status,confidence_level,source_record_status ORDER BY qc_status,confidence_level,source_record_status;
-- rain_qc_daily_by_status
SELECT daily_quality_status,COUNT(*) rows_n,SUM(verified_daily_rain_mm IS NULL) verified_null,MIN(local_date) first_date,MAX(local_date) last_date FROM loucka_reconstruction.rain_qc_daily_202107 GROUP BY daily_quality_status ORDER BY daily_quality_status;
-- reference_daily_by_quality
SELECT quality_status,source_resolution,COUNT(*) rows_n,MIN(local_date) first_date,MAX(local_date) last_date FROM loucka_reconstruction.reference_daily GROUP BY quality_status,source_resolution ORDER BY quality_status,source_resolution;
-- reference_obs_by_quality
SELECT station_id,quality_status,source_resolution,COUNT(*) rows_n,MIN(observed_at_utc) min_utc,MAX(observed_at_utc) max_utc FROM loucka_reconstruction.reference_observations GROUP BY station_id,quality_status,source_resolution ORDER BY station_id,quality_status,source_resolution;
-- wh1080_candidates_by_status
SELECT source_db,status,COUNT(*) rows_n,MIN(target_time) min_target,MAX(target_time) max_target,MIN(time_offset_sec) min_offset,MAX(time_offset_sec) max_offset FROM loucka_reconstruction.wh1080_missing_5min_candidates_20261030 GROUP BY source_db,status ORDER BY source_db,status;
